 namespace Clinic.Lab;

 public sealed class LabSync
 {
     private readonly HttpClient _http;
     private readonly ILogger<LabSync> _log;
     private readonly LabOptions _options;

     public LabSync(HttpClient http, ILogger<LabSync> log, LabOptions options)
     {
         _http = http;
         _log = log;
         _options = options;
     }

+    public async Task<bool> PushAsync(LabOrder order, CancellationToken ct)
+    {
+        var url = $"{_options.BaseUrl}/orders?token={_options.ApiKey}";
+        _log.LogInformation("Отправляю заказ {OrderId} на {Url}", order.Id, url);
+
+        using var response = await _http.PostAsJsonAsync(url, order, ct);
+        _log.LogInformation("Лаборатория ответила {Status}", response.StatusCode);
+
+        return response.IsSuccessStatusCode;
+    }
 }
